const float kFocLen = 5.0;
const float kCliffA = 0.5;
const float kCliffB = 0.5;
const int kMaxIter = 300; // max fractal iterations
const int kMaxStep = 35;  // max raymarch steps


//-------------------------------------------------------------------------------
vec3 pal(float t, vec3 a, vec3 b, vec3 c, vec3 d)
{
    return a + b*cos( 6.28318*(c*t+d) );
}

//-------------------------------------------------------------------------------
mat3 getCamera(vec3 ro, vec3 ta, float cr)
{
	vec3 cw = normalize(ta-ro);
	vec3 cp = vec3(sin(cr), 0.0, cos(cr));
	vec3 cu = normalize( cross(cp,cw) );
	vec3 cv = normalize( cross(cw,cu) );
    return mat3( cu, cv, cw );
}

//--------------------------------------------------------------------------------
vec3 rayPlane(vec3 ro, vec3 rd)
{
    float lh = max(0.0, abs(rd.z) > 1e-4 ? -ro.z / rd.z : 0.0);
    return ro + (rd * lh);
}

//--------------------------------------------------------------------------------
float cliffDist(float x, float z)
{
    // 'cliff' function used is f(x) = b/(x + a) - b/a
    // see https://www.shadertoy.com/view/mt3SDN for estimated dist to 1D function
    x += kCliffA;
    float f = kCliffB / x - kCliffB / kCliffA;
    // Derivative f'(x)
    float df = -kCliffB / (x * x);

    float dist = (z - f);
    dist /= sqrt( 1.0 + df*df );

    return dist;
}

float cliffZ(float x)
{   
    x += kCliffA;
    float z = kCliffB / x - kCliffB/kCliffA;
    return min(z, 0.0); // z always neg
}

//--------------------------------------------------------------------------------
vec2 julia(vec2 z, vec2 c )
{
    // DF of the Julia set z^2 + c
    float dz2 = 1.0;
    float z2 = dot(z,z);
    const float B = 256.0;
    float n = 0.0;

    for(int i=0; i<kMaxIter; i++)
    {
        dz2 *= 4.0*z2;
        z  = vec2( z.x*z.x - z.y*z.y, 2.0*z.x*z.y ) + c;
        z2 = dot(z,z);

        if( z2 > B*B )
        {
            // diverge, ie. we're outside of the julia set
            // see https://iquilezles.org/articles/distancefractals
            float de = 0.5*log(z2)*sqrt(z2/dz2); // dist estimate
            float si = (n - log2(log2(z2)) + 4.0); // smooth iteration count optimized
            return vec2(de,si);  
        }
        n += 1.0;
    }

    return vec2(0.0);
}

// Julia + cliff
vec2 map(vec3 p, vec2 c)
{
    vec2 di = julia(p.xy, c);
    float d = cliffDist(di.x, p.z);
    di.x = min(d, di.x);
    return di;
}

float juliaZ(vec2 p, vec2 c)
{
    vec2 di = julia(p, c);
    return cliffZ(di.x);
}

vec3 getNormal(vec2 p, vec2 c)
{
    const float eps = 0.001;
    const vec2 h = vec2(eps,0);

    return normalize( vec3( juliaZ(p-h.xy, c) - juliaZ(p+h.xy, c),
                            2.0*h.x,
                            juliaZ(p-h.yx, c) - juliaZ(p+h.yx, c) ) );
}

vec3 renderJulia(vec3 ro, vec3 rd, vec2 c)
{
    vec2 di = vec2(0.0);
    float d = 0.0;
    vec3 p = ro;

    // raymarch
    for(int i=0; i<kMaxStep; i++)
    {
        di = map(p, c);

        if( abs(di.x) < 0.001) break;
        p += rd*di.x;
    }

    vec3 col = vec3(1.0); 
    if(di.y > 0.0)
    {
        col = pal( di.y*0.01, vec3(0.5),vec3(0.5),vec3(1.0),vec3(0.8)-vec3(-0.288,-0.183,0.025) );

        // basic lighting
        vec3 n = getNormal(p.xy, c);
        vec3 l = normalize(vec3(1.0));
        col *= max(0.15, dot(n, l));
    }

	return pow(col,vec3(0.9));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //-----------------------------------------------
    // camera
    float hcam = 0.5 + 0.3*(cos(iTime*0.25)*0.5+0.5);
    float dcam = 1.6 + 0.4*(sin(iTime*0.1)*0.5+0.5);
    float an = 0.5+iTime*0.025;
    vec3  ro = dcam*vec3(sin(an),cos(an),hcam);
    vec3  ta = vec3(0.2*cos(iTime*0.11), 0.2*sin(iTime*0.21), 0.0 );
    mat3x3 cam = getCamera(ro,ta,0.0);

    //-----------------------------------------------
    // c variations
    float inter = 0.0; 
    float delta = 0.75;
    float at = mod( (iTime+.5)/10.0, 9.0 );

    vec2 c = vec2(0.355, 0.355);
    c = mix( c, vec2(0.355, 0.340), smoothstep(inter,inter+delta,at) ); inter++;
    c = mix( c, vec2(0.367, 0.316), smoothstep(inter,inter+delta,at) ); inter++;
    c = mix( c, vec2(0.371, 0.315), smoothstep(inter,inter+delta,at) ); inter++;
    c = mix( c, vec2(0.385, 0.32), smoothstep(inter,inter+delta,at) ); inter++;
    c = mix( c, vec2(0.388, 0.35), smoothstep(inter,inter+delta,at) ); inter++;
    c = mix( c, mix(vec2(0.388, 0.35),vec2(0.349, 0.347),0.75), smoothstep(inter,inter+delta,at) ); inter++;

    //-----------------------------------------------
    // rendering
    vec2 p = (-iResolution.xy + 2.0*fragCoord.xy)/iResolution.y;
    vec3 rd = normalize( cam*vec3(p.xy,kFocLen) );

    ro = rayPlane(ro, rd);
    vec3 col = renderJulia(ro, rd, c);

    // add vignette
    vec2 vp = fragCoord / iResolution.xy;
    col *= 0.5 + 0.5*pow( 16.0*vp.x*vp.y*(1.0-vp.x)*(1.0-vp.y), 0.1 );

    fragColor = vec4(col,1.0);
}
